using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Zyven.Domain;
namespace Zyven.Infrastructure;

public sealed class PixRecoveryConfigurationMap : IEntityTypeConfiguration<PixRecoveryConfiguration> { public void Configure(EntityTypeBuilder<PixRecoveryConfiguration> b) { b.HasAlternateKey(x => new { x.Id, x.OrganizationId }); b.HasIndex(x => new { x.OrganizationId, x.OfferId }).IsUnique(); b.HasOne<Offer>().WithMany().HasForeignKey(x => new { x.OfferId, x.OrganizationId }).HasPrincipalKey(x => new { x.Id, x.OrganizationId }).OnDelete(DeleteBehavior.Cascade); } }
public sealed class PixRecoveryMessageMap : IEntityTypeConfiguration<PixRecoveryMessage> { public void Configure(EntityTypeBuilder<PixRecoveryMessage> b) { b.HasIndex(x => new { x.ConfigurationId, x.Version, x.Position }).IsUnique(); b.Property(x => x.EmailText).HasMaxLength(4000); b.Property(x => x.TelegramText).HasMaxLength(4000); b.HasOne<PixRecoveryConfiguration>().WithMany().HasForeignKey(x => new { x.ConfigurationId, x.OrganizationId }).HasPrincipalKey(x => new { x.Id, x.OrganizationId }).OnDelete(DeleteBehavior.Cascade); } }
public sealed class PixRecoveryExecutionMap : IEntityTypeConfiguration<PixRecoveryExecution> { public void Configure(EntityTypeBuilder<PixRecoveryExecution> b) { b.HasAlternateKey(x => new { x.Id, x.OrganizationId }); b.HasIndex(x => x.PaymentId).IsUnique(); b.HasIndex(x => new { x.Status, x.NextRunAt }); b.Property(x => x.Channel).HasMaxLength(20); b.Property(x => x.Status).HasMaxLength(30); b.HasOne<PixRecoveryConfiguration>().WithMany().HasForeignKey(x => new { x.ConfigurationId, x.OrganizationId }).HasPrincipalKey(x => new { x.Id, x.OrganizationId }).OnDelete(DeleteBehavior.Restrict); b.HasOne<Payment>().WithMany().HasForeignKey(x => new { x.PaymentId, x.OrganizationId }).HasPrincipalKey(x => new { x.Id, x.OrganizationId }).OnDelete(DeleteBehavior.Restrict); } }
public sealed class PixRecoveryAttemptMap : IEntityTypeConfiguration<PixRecoveryAttempt> { public void Configure(EntityTypeBuilder<PixRecoveryAttempt> b) { b.HasIndex(x => new { x.ExecutionId, x.Position }).IsUnique(); b.Property(x => x.Channel).HasMaxLength(20); b.Property(x => x.Status).HasMaxLength(20); b.HasOne<PixRecoveryExecution>().WithMany().HasForeignKey(x => new { x.ExecutionId, x.OrganizationId }).HasPrincipalKey(x => new { x.Id, x.OrganizationId }).OnDelete(DeleteBehavior.Cascade); } }
public sealed class BotCheckoutReferenceMap : IEntityTypeConfiguration<BotCheckoutReference> { public void Configure(EntityTypeBuilder<BotCheckoutReference> b) { b.HasIndex(x => x.Hash).IsUnique(); b.Property(x => x.Hash).HasMaxLength(64); b.HasIndex(x => x.ExpiresAt); b.HasOne<Offer>().WithMany().HasForeignKey(x => new { x.OfferId, x.OrganizationId }).HasPrincipalKey(x => new { x.Id, x.OrganizationId }).OnDelete(DeleteBehavior.Cascade); b.HasOne<TelegramIntegration>().WithMany().HasForeignKey(x => x.TelegramIntegrationId).OnDelete(DeleteBehavior.Restrict); } }
public sealed class BotCheckoutBindingMap : IEntityTypeConfiguration<BotCheckoutBinding> { public void Configure(EntityTypeBuilder<BotCheckoutBinding> b) { b.HasKey(x => x.CheckoutId); b.HasOne<CheckoutSession>().WithOne().HasForeignKey<BotCheckoutBinding>(x => x.CheckoutId).OnDelete(DeleteBehavior.Cascade); b.HasOne<TelegramIntegration>().WithMany().HasForeignKey(x => x.TelegramIntegrationId).OnDelete(DeleteBehavior.Restrict); } }
